package com.tuap.backend.auth; import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth/consents") public class ConsentController { private final ConsentService service; public ConsentController(ConsentService s){service=s;} @GetMapping public ResponseEntity<Map<String,Object>> status(@AuthenticationPrincipal AuthenticatedUser u){return ResponseEntity.ok(service.status(u));} @PutMapping("/marketing") public ResponseEntity<Void> marketing(@AuthenticationPrincipal AuthenticatedUser u,@RequestBody Map<String,Boolean> body){Boolean accepted=body.get("accepted");if(accepted==null)return ResponseEntity.badRequest().build();service.marketing(u,accepted);return ResponseEntity.noContent().build();} }
